        align-self: flex-end;
      }

      .bot .text {
        background-color: #008CBA;
        color: #fff;
      }
    </style>
  </head>
  <body>
    <button id="show-modal">Show Modal</button>

    <!-- Modal -->
    <div id="myModal" class="modal">
      <!-- Modal content -->
      <div class="modal-content">
        <span class="close">&times;</span>
        <div class="message">
          <img src="https://via.placeholder.com/40" alt="Bot Avatar" />
          <div class="text">Hello, how can I assist you today?</div>
        </div>
        <div class="message bot">
          <img src="https://via.placeholder.com/40" alt="Bot Avatar" />
          <div class="text">Sure, I'm here to help. What's on your mind?</div>
        </div>
        <div class="message">
          <img src="https://via.placeholder.com/40" alt="User Avatar" />
          <div class="text">I need help with my online shopping order.</div>
        </div>
        <div class="message bot">
          <img src="https://via.placeholder.com/40" alt="Bot Avatar" />
